create table if not exists public.manpower_targets(
  id uuid primary key default gen_random_uuid(),
  report_type text not null check (report_type in ('nursing','support')),
  source_period text not null,
  group_name text not null,
  unit_name text not null,
  position text not null,
  quota integer default 0 check (quota is null or quota >= 0),
  sort_group integer not null default 0,
  sort_unit integer not null default 0,
  source_note text not null default '',
  unique (report_type, source_period, group_name, unit_name, position)
);

alter table public.manpower_targets enable row level security;
grant select, update on public.manpower_targets to authenticated;

drop policy if exists manpower_targets_sel on public.manpower_targets;
drop policy if exists manpower_targets_upd on public.manpower_targets;
create policy manpower_targets_sel on public.manpower_targets
  for select to authenticated using (my_role() <> 'none');
create policy manpower_targets_upd on public.manpower_targets
  for update to authenticated
  using (my_role() = 'admin' or (my_role() = 'unit_head' and (my_unit() = '*' or my_unit() = group_name or my_unit() = unit_name)))
  with check (my_role() = 'admin' or (my_role() = 'unit_head' and (my_unit() = '*' or my_unit() = group_name or my_unit() = unit_name)));


-- Initial staffing framework from the November 2569 source workbook.
on conflict (report_type, source_period, group_name, unit_name, position) do nothing;
